import { useEffect, useRef, useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Wallet } from "lucide-react";
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion";

const STORAGE_KEY = "payplate_intro_v2";
const FIRST_LAUNCH_KEY = "payplate_first_launch_v2";

// OLED-black brand palette — matches the dark theme tokens exactly
// (--background: #050505, --primary: #00D27A, --accent: #00E5A8)
const BG = "#050505";
const PRIMARY = "#00D27A";
const ACCENT = "#00E5A8";

const TAGLINE_LINES = ["Student Food.", "Smart Payments.", "Real Savings."];

type Phase =
  | "glow"       // 1-2: black bg + ambient glow ramps in
  | "coin"       // 3: 3D coin rotates in
  | "plate"      // 4: coin morphs into a plate
  | "food"       // 5: food elements appear with depth
  | "logo"       // 6: logo fades in
  | "tagline"    // 7: three-line tagline
  | "progress"   // 8: glowing loading bar
  | "wallet"     // 9: plate transitions into wallet icon
  | "out";       // 10: fade into home

const PHASE_TIMINGS: { phase: Phase; at: number }[] = [
  { phase: "glow", at: 0 },
  { phase: "coin", at: 150 },
  { phase: "plate", at: 650 },
  { phase: "food", at: 950 },
  { phase: "logo", at: 1350 },
  { phase: "tagline", at: 1650 },
  { phase: "progress", at: 2050 },
  { phase: "wallet", at: 2450 },
  { phase: "out", at: 2700 },
];

const TOTAL_DURATION = 3000;

export function CinematicSplash({ onComplete }: { onComplete: () => void }) {
  const reduced = usePrefersReducedMotion();
  const [phase, setPhase] = useState<Phase>("glow");
  const [progress, setProgress] = useState(0);
  const doneRef = useRef(false);

  const finish = () => {
    if (doneRef.current) return;
    doneRef.current = true;
    localStorage.setItem(FIRST_LAUNCH_KEY, "done");
    onComplete();
  };

  useEffect(() => {
    // Respect prefers-reduced-motion: skip straight past the animated intro
    if (reduced) {
      finish();
      return;
    }

    const timers = PHASE_TIMINGS.map(({ phase: p, at }) =>
      setTimeout(() => setPhase(p), at)
    );

    // Loading bar fills across the "progress" -> "wallet" window
    const mountedAt = Date.now();
    const progressStart = PHASE_TIMINGS.find((p) => p.phase === "progress")!.at;
    const progressEnd = PHASE_TIMINGS.find((p) => p.phase === "wallet")!.at;
    const progressWindow = progressEnd - progressStart;
    const progressTimer = setInterval(() => {
      const elapsed = Date.now() - mountedAt;
      const pct = Math.min(
        100,
        Math.max(0, ((elapsed - progressStart) / progressWindow) * 100)
      );
      setProgress(pct);
    }, 30);

    const outTimer = setTimeout(finish, TOTAL_DURATION);

    return () => {
      timers.forEach(clearTimeout);
      clearInterval(progressTimer);
      clearTimeout(outTimer);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [reduced]);

  const showCoin = phase === "coin";
  const showPlate = phase === "plate" || phase === "food" || phase === "logo" || phase === "tagline" || phase === "progress";
  const showWallet = phase === "wallet";
  const showFood = phase === "food" || phase === "logo" || phase === "tagline" || phase === "progress";
  const showLogo = phase === "logo" || phase === "tagline" || phase === "progress" || phase === "wallet";
  const showTagline = phase === "tagline" || phase === "progress" || phase === "wallet";
  const showProgress = phase === "progress" || phase === "wallet";

  return (
    <motion.div
      exit={{ opacity: 0 }}
      transition={{ duration: 0.5, ease: "easeInOut" }}
      className="fixed inset-0 z-[300] flex flex-col items-center justify-center overflow-hidden"
      style={{ background: BG, willChange: "opacity" }}
    >
      {/* 1-2. OLED black base + soft ambient green glow ramping in */}
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ duration: 1.2, ease: "easeOut" }}
        className="absolute left-1/2 top-1/2 size-[36rem] -translate-x-1/2 -translate-y-1/2 rounded-full"
        style={{
          background: `radial-gradient(circle, ${PRIMARY}33 0%, transparent 70%)`,
          willChange: "opacity",
        }}
      />
      <div
        className="absolute right-[15%] bottom-[20%] size-64 rounded-full blur-[70px]"
        style={{ background: `${ACCENT}22` }}
      />

      {/* Central stage: coin -> plate -> wallet, cross-faded */}
      <div className="relative z-10 flex h-40 items-center justify-center">
        <AnimatePresence mode="wait">
          {showCoin && (
            <motion.div
              key="coin"
              initial={{ scale: 0.3, rotateY: -180, opacity: 0 }}
              animate={{ scale: 1, rotateY: 0, opacity: 1 }}
              exit={{ scale: 0.6, opacity: 0 }}
              transition={{ duration: 0.5, ease: "easeOut" }}
              style={{ transformStyle: "preserve-3d", willChange: "transform, opacity" }}
              className="grid size-28 place-items-center rounded-full text-5xl font-black text-white shadow-2xl"
            >
              <div
                className="grid size-28 place-items-center rounded-full"
                style={{
                  background: `linear-gradient(135deg, ${PRIMARY}, ${ACCENT})`,
                  boxShadow: `0 0 60px ${PRIMARY}73`,
                }}
              >
                P
              </div>
            </motion.div>
          )}

          {showPlate && !showWallet && (
            <motion.div
              key="plate"
              initial={{ scale: 0.7, rotate: -20, opacity: 0 }}
              animate={{ scale: 1, rotate: 0, opacity: 1 }}
              exit={{ scale: 0.7, opacity: 0 }}
              transition={{ duration: 0.5, ease: "easeOut" }}
              style={{ willChange: "transform, opacity" }}
              className="relative grid size-28 place-items-center rounded-full"
            >
              <div
                className="grid size-28 place-items-center rounded-full text-5xl"
                style={{
                  background: `linear-gradient(135deg, ${PRIMARY}, ${ACCENT})`,
                  boxShadow: `0 0 60px ${PRIMARY}73`,
                }}
              >
                🍽️
              </div>

              {/* 5. Food elements orbiting with subtle depth */}
              <AnimatePresence>
                {showFood && (
                  <>
                    <motion.span
                      initial={{ opacity: 0, x: -10, y: -10, scale: 0.5 }}
                      animate={{ opacity: 1, x: -46, y: -36, scale: 1, rotate: [0, -6, 0] }}
                      transition={{ duration: 0.5, rotate: { repeat: Infinity, duration: 2.2 } }}
                      className="absolute text-2xl drop-shadow-lg"
                      style={{ willChange: "transform, opacity" }}
                    >
                      🍔
                    </motion.span>
                    <motion.span
                      initial={{ opacity: 0, x: 10, y: -10, scale: 0.5 }}
                      animate={{ opacity: 1, x: 44, y: -30, scale: 1, rotate: [0, 6, 0] }}
                      transition={{ duration: 0.5, delay: 0.08, rotate: { repeat: Infinity, duration: 2.4 } }}
                      className="absolute text-xl drop-shadow-lg"
                      style={{ willChange: "transform, opacity" }}
                    >
                      🍟
                    </motion.span>
                    <motion.span
                      initial={{ opacity: 0, y: 10, scale: 0.5 }}
                      animate={{ opacity: 1, x: 6, y: 42, scale: 1, rotate: [0, -4, 0] }}
                      transition={{ duration: 0.5, delay: 0.16, rotate: { repeat: Infinity, duration: 2.6 } }}
                      className="absolute text-xl drop-shadow-lg"
                      style={{ willChange: "transform, opacity" }}
                    >
                      🥤
                    </motion.span>
                  </>
                )}
              </AnimatePresence>
            </motion.div>
          )}

          {showWallet && (
            <motion.div
              key="wallet"
              initial={{ scale: 0.6, opacity: 0, rotate: 15 }}
              animate={{ scale: 1, opacity: 1, rotate: 0 }}
              exit={{ scale: 0.8, opacity: 0 }}
              transition={{ duration: 0.45, ease: "easeOut" }}
              style={{ willChange: "transform, opacity" }}
              className="grid size-28 place-items-center rounded-full"
            >
              <div
                className="grid size-28 place-items-center rounded-full"
                style={{
                  background: `linear-gradient(135deg, ${PRIMARY}, ${ACCENT})`,
                  boxShadow: `0 0 60px ${PRIMARY}73`,
                }}
              >
                <Wallet className="size-12 text-white" strokeWidth={2.25} />
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      {/* 6. Logo */}
      <AnimatePresence>
        {showLogo && (
          <motion.h1
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.4 }}
            style={{ willChange: "transform, opacity" }}
            className="relative z-10 mt-6 font-heading text-4xl font-black tracking-tight text-white"
          >
            PayPlate
          </motion.h1>
        )}
      </AnimatePresence>

      {/* 7. Three-line tagline */}
      <AnimatePresence>
        {showTagline && (
          <motion.div
            initial={{ opacity: 0, y: 12 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.4 }}
            style={{ willChange: "transform, opacity" }}
            className="relative z-10 mt-4 text-center"
          >
            {TAGLINE_LINES.map((line, i) => (
              <motion.p
                key={line}
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ delay: i * 0.08, duration: 0.3 }}
                className="text-sm font-bold leading-relaxed"
                style={{ color: i === 2 ? PRIMARY : "#A8A8A8" }}
              >
                {line}
              </motion.p>
            ))}
          </motion.div>
        )}
      </AnimatePresence>

      {/* 8. Glowing loading bar */}
      <AnimatePresence>
        {showProgress && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 0.25 }}
            className="relative z-10 mt-8 w-44"
          >
            <div className="h-1 overflow-hidden rounded-full" style={{ background: "rgba(255,255,255,0.1)" }}>
              <motion.div
                className="h-full rounded-full"
                style={{
                  width: `${progress}%`,
                  background: `linear-gradient(90deg, ${PRIMARY}, ${ACCENT})`,
                  boxShadow: `0 0 12px ${PRIMARY}`,
                  willChange: "width",
                }}
              />
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
}

export function QuickSplash({ onComplete }: { onComplete: () => void }) {
  const reduced = usePrefersReducedMotion();

  useEffect(() => {
    const t = setTimeout(() => {
      localStorage.setItem(STORAGE_KEY, "1");
      onComplete();
    }, reduced ? 0 : 700);
    return () => clearTimeout(t);
  }, [onComplete, reduced]);

  return (
    <motion.div
      exit={{ opacity: 0 }}
      transition={{ duration: 0.3 }}
      className="fixed inset-0 z-[300] flex flex-col items-center justify-center"
      style={{ background: BG }}
    >
      <motion.div
        animate={reduced ? undefined : { scale: [1, 1.06, 1] }}
        transition={{ duration: 0.8, repeat: Infinity }}
        className="grid size-24 place-items-center rounded-full"
        style={{
          background: `linear-gradient(135deg, ${PRIMARY}, ${ACCENT})`,
          boxShadow: `0 0 40px ${PRIMARY}66`,
        }}
      >
        <span className="font-heading text-5xl font-black text-white">P</span>
      </motion.div>
      <p className="mt-5 font-heading text-2xl font-black text-white">PayPlate</p>
    </motion.div>
  );
}

export function SplashWrapper({ children }: { children: React.ReactNode }) {
  const [splashType, setSplashType] = useState<"cinematic" | "quick" | "none" | null>(null);

  useEffect(() => {
    const firstLaunch = !localStorage.getItem(FIRST_LAUNCH_KEY);
    const returning = localStorage.getItem(STORAGE_KEY);
    if (firstLaunch) {
      setSplashType("cinematic");
    } else if (!returning) {
      setSplashType("quick");
    } else {
      setSplashType("none");
    }
  }, []);

  if (splashType === null) return null; // wait for mount

  return (
    <AnimatePresence mode="wait">
      {splashType === "cinematic" && (
        <CinematicSplash key="cinematic" onComplete={() => setSplashType("none")} />
      )}
      {splashType === "quick" && (
        <QuickSplash key="quick" onComplete={() => setSplashType("none")} />
      )}
      {splashType === "none" && (
        <motion.div key="app" initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.3 }}>
          {children}
        </motion.div>
      )}
    </AnimatePresence>
  );
}

// Reset splash for testing
export function resetSplash() {
  localStorage.removeItem(STORAGE_KEY);
  localStorage.removeItem(FIRST_LAUNCH_KEY);
}

import { NavLink } from "@/lib/router-compat";
import {
  Home, Receipt, Wallet, Star, User, QrCode,
  type LucideIcon,
} from "lucide-react";
import { useCart } from "@/contexts/cart-context";
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion";
import { motion } from "framer-motion";
import { cn } from "@/lib/utils";

const NAV_ITEMS: { to: string; label: string; icon: LucideIcon }[] = [
  { to: "/home",      label: "Home",    icon: Home    },
  { to: "/orders",   label: "Orders",  icon: Receipt  },
  { to: "/wallet",   label: "Wallet",  icon: Wallet   },
  { to: "/rewards",  label: "Rewards", icon: Star     },
  { to: "/profile",  label: "Profile", icon: User     },
];

const SIDEBAR_ITEMS
  { to: "/home",          label: "Home",          icon: Home    },
  { to: "/restaurants",   label: "Restaurants",   icon: Home    },
  { to: "/orders",        label: "Orders",        icon: Receipt },
  { to: "/wallet",        label: "Wallet",        icon: Wallet  },
  { to: "/rewards",       label: "Rewards",       icon: Star    },
  { to: "/cart",          label: "Cart",          icon: Receipt },
  { to: "/profile",       label: "Profile",       icon: User    },
  { to: "/notifications", label: "Notifications", icon: Home    },
  { to: "/settings",      label: "Settings",      icon: Home    },
  { to: "/support",       label: "Support",       icon: Home    },
];

/* ─── Bottom Navigation (mobile) ─── */
export function BottomNav() {
  const { itemCount } = useCart();
  const reduced = usePrefersReducedMotion();

  const left  = NAV_ITEMS.slice(0, 2);   // Home, Orders
  const right = NAV_ITEMS.slice(2);      // Wallet, Rewards, Profile

  return (
    <nav
      className="fixed bottom-0 left-0 right-0 z-40 border-t border-border lg:hidden"
      style={{ paddingBottom: "env(safe-area-inset-bottom)", background: "rgba(10,10,10,0.97)", backdropFilter: "blur(20px)" }}
      aria-label="Primary navigation"
    >
      <div className="relative mx-auto flex max-w-md items-end justify-around px-2 pt-2 pb-2">
        {left.map(({ to, label, icon: Icon }) => (
          <NavTab key={to} to={to} label={label} icon={Icon} reduced={reduced}
            badge={to === "/orders" ? itemCount : 0} />
        ))}

        {/* Centre QR FAB */}
        <div className="relative -mt-7 flex w-16 shrink-0 flex-col items-center">
          <NavLink
            to="/wallet"
            aria-label="Scan QR to pay"
            className="relative grid size-16 place-items-center rounded-2xl bg-primary text-white transition-transform active:scale-90"
            style={{ boxShadow: "0 8px 28px rgba(0,210,122,0.45)" }}
          >
            {!reduced && (
              <motion.span
                animate={{ scale: [1, 1.25, 1], opacity: [0.5, 0, 0.5] }}
                transition={{ duration: 2.2, repeat: Infinity, ease: "easeInOut" }}
                className="absolute inset-0 rounded-2xl bg-primary/40"
              />
            )}
            <QrCode size={26} className="relative" />
          </NavLink>
          <span className="mt-0.5 text-[10px] font-bold text-muted-foreground">Pay</span>
        </div>

        {right.map(({ to, label, icon: Icon }) => (
          <NavTab key={to} to={to} label={label} icon={Icon} reduced={reduced} />
        ))}
      </div>
    </nav>
  );
}

function NavTab({
  to, label, icon: Icon, reduced, badge = 0,
}: {
  to: string; label: string; icon: LucideIcon; reduced: boolean; badge?: number;
}) {
  return (
    <NavLink
      to={to}
      className="relative flex flex-1 flex-col items-center gap-0.5 py-1"
      aria-label={label}
    >
      {({ isActive }) => (
        <>
          <span className="relative grid place-items-center">
            {isActive && !reduced && (
              <motion.span
                layoutId="nav-indicator"
                className="absolute -inset-x-3 -inset-y-1.5 rounded-xl bg-primary/12"
                transition={{ type: "spring", stiffness: 400, damping: 32 }}
              />
            )}
            <Icon
              size={22}
              strokeWidth={isActive ? 2.5 : 1.8}
              className={cn("relative transition-colors", isActive ? "text-primary" : "text-muted-foreground")}
            />
            {badge > 0 && (
              <span className="absolute -right-1.5 -top-1 grid min-w-[16px] place-items-center rounded-full bg-primary px-1 text-[9px] font-black text-white">
                {badge}
              </span>
            )}
          </span>
          <span className={cn("relative text-[10px] font-bold transition-colors",
            isActive ? "text-primary" : "text-muted-foreground")}>
            {label}
          </span>
        </>
      )}
    </NavLink>
  );
}

/* ─── Sidebar (desktop) ─── */
export function Sidebar() {
  const { itemCount } = useCart();

  return (
    <aside className="fixed left-0 top-0 bottom-0 z-30 hidden w-64 flex-col border-r border-border bg-card p-5 lg:flex">
      <NavLink to="/home" className="mb-8 flex items-center gap-2.5">
        <div className="grid size-10 place-items-center rounded-xl bg-primary text-white shadow-lift">
          <span className="font-heading text-lg font-black">P</span>
        </div>
        <span className="font-heading text-xl font-black">PayPlate</span>
      </NavLink>

      <nav className="flex flex-1 flex-col gap-0.5">
        {SIDEBAR_ITEMS.map(({ to, label, icon: Icon }) => (
          <NavLink
            key={to}
            to={to}
            className={({ isActive }) =>
              cn(
                "flex items-center gap-3 rounded-xl px-4 py-2.5 text-sm font-bold transition-all",
                isActive
                  ? "bg-primary/10 text-primary"
                  : "text-muted-foreground hover:bg-muted hover:text-text",
              )
            }
          >
            <Icon size={18} strokeWidth={1.8} />
            <span>{label}</span>
            {to === "/cart" && itemCount > 0 && (
              <span className="ml-auto grid min-w-5 place-items-center rounded-full bg-primary px-1.5 text-xs font-black text-white">
                {itemCount}
              </span>
            )}
          </NavLink>
        ))}
      </nav>

      <div className="rounded-2xl bg-primary/5 p-4">
        <p className="text-xs font-bold text-muted-foreground">Need help?</p>
        <NavLink to="/support" className="mt-1 block text-sm font-black text-primary">
          Contact support →
        </NavLink>
      </div>
    </aside>
  );
}

import type { ReactNode } from "react";
import { Navigate, useLocation } from "@/lib/router-compat";
import { useAuth } from "@/contexts/auth-context";

export function ProtectedRoute({ children }: { children: ReactNode }) {
  const { isAuthenticated, isLoading } = useAuth();
  const location = useLocation();

  if (isLoading) {
    return (
      <div className="grid min-h-screen place-items-center">
        <div className="size-8 rounded-full border-4 border-muted border-t-primary" style={{ animation: "spin 1s linear infinite" }} />
      </div>
    );
  }

  if (!isAuthenticated) {
    return <Navigate to="/login" state={{ from: location }} replace />;
  }

  return <>{children}</>;
}

import { Link } from "@/lib/router-compat";

export function Breadcrumb({ items }: { items: { title: string; to?: string }[] }) {
  return (
    <nav aria-label="Breadcrumb" className="text-sm">
      <ol className="flex items-center gap-2">
        {items.map((it, idx) => (
          <li key={idx} className="inline-flex items-center">
            {it.to ? (
              <Link to={it.to} className="text-muted-foreground hover:text-text">
                {it.title}
              </Link>
            ) : (
              <span className="text-text font-bold">{it.title}</span>
            )}
            {idx < items.length - 1 ? <span className="mx-2">/</span> : null}
          </li>
        ))}
      </ol>
    </nav>
  );
}

import { Link, useNavigate } from "@/lib/router-compat";
import { Search, Moon, Sun, Code, ShoppingBag, MapPin, Bell } from "lucide-react";
import { useTheme } from "@/contexts/theme-context";
import { useCart } from "@/contexts/cart-context";
import { useAuth } from "@/contexts/auth-context";
import { cn } from "@/lib/utils";
import { useState } from "react";

export function TopNavigation() {
  const { theme, toggleTheme, setTheme } = useTheme();
  const { itemCount } = useCart();
  const { isAuthenticated } = useAuth();
  const navigate = useNavigate();
  const [searchValue, setSearchValue] = useState("");

  function handleSearch(e: React.FormEvent) {
    e.preventDefault();
    if (searchValue.trim()) navigate(`/restaurants?q=${encodeURIComponent(searchValue)}`);
  }

  return (
    <header className="sticky top-0 z-40 w-full border-b border-border bg-background/85 backdrop-blur-xl">
      <div className="mx-auto flex max-w-7xl items-center justify-between gap-3 px-5 py-3 lg:px-8">
        <Link to={isAuthenticated ? "/home" : "/"} className="flex shrink-0 items-center gap-2">
          <div className="grid size-9 place-items-center rounded-xl bg-primary text-white shadow-lift">
            <span className="font-heading text-sm font-black">P</span>
          </div>
          <span className="hidden font-heading text-lg font-black sm:block">PayPlate</span>
        </Link>

        {isAuthenticated && (
          <form onSubmit={handleSearch} className="hidden flex-1 max-w-md sm:block">
            <div className="relative">
              <Search size={18} className="pointer-events-none absolute left-4 top-1/2 -translate-y-1/2 text-muted-foreground" />
              <input
                type="text"
                placeholder="Search restaurants, meals…"
                value={searchValue}
                onChange={(e) => setSearchValue(e.target.value)}
                className="h-11 w-full rounded-2xl border border-border bg-card pl-11 pr-4 text-sm font-medium outline-none transition-all focus:border-primary focus:ring-2 focus:ring-primary/20"
                aria-label="Search"
              />
            </div>
          </form>
        )}

        <div className="flex items-center gap-2">
          {isAuthenticated && (
            <>
              <Link
                to="/notifications"
                className="relative grid size-11 place-items-center rounded-2xl border border-border bg-card shadow-sm"
                aria-label="Notifications"
              >
                <Bell size={18} />
                <span className="absolute right-2.5 top-2.5 size-2 rounded-full bg-danger ring-2 ring-card" />
              </Link>

              <Link
                to="/cart"
                className="relative grid size-11 place-items-center rounded-2xl border border-border bg-card shadow-sm"
                aria-label={`Cart with ${itemCount} items`}
              >
                <ShoppingBag size={18} />
                {itemCount > 0 && (
                  <span className="absolute -right-1.5 -top-1.5 grid min-w-5 place-items-center rounded-full bg-primary px-1 text-[10px] font-black text-white">
                    {itemCount}
                  </span>
                )}
              </Link>
            </>
          )}

          <button
            aria-label="Toggle theme"
            onClick={toggleTheme}
            className="grid size-11 place-items-center rounded-2xl border border-border bg-card shadow-sm transition-transform hover:-translate-y-0.5"
          >
            {theme === "dark" ? <Sun size={18} /> : <Moon size={18} />}
          </button>

          <button
            aria-label="Developer theme"
            title="Toggle developer theme"
            onClick={() => setTheme(theme === "dev" ? "light" : "dev")}
            className="hidden size-11 place-items-center rounded-2xl border border-border bg-card shadow-sm transition-transform hover:-translate-y-0.5 lg:grid"
          >
            <Code size={16} />
          </button>

          {isAuthenticated ? (
            <Link
              to="/profile"
              className="grid size-11 place-items-center rounded-2xl border border-border bg-card font-bold shadow-sm transition-transform hover:-translate-y-0.5"
              aria-label="Profile"
            >
              <span className="text-sm">Me</span>
            </Link>
          ) : (
            <Link
              to="/login"
              className={cn(
                "inline-flex h-11 items-center rounded-2xl bg-primary px-4 text-sm font-extrabold text-white shadow-lift transition-transform hover:-translate-y-0.5",
              )}
            >
              Sign in
            </Link>
          )}
        </div>
      </div>
    </header>
  );
}

# C# Integration Guide (examples)

This document provides lightweight examples and guidance for integrating a C# (ASP.NET Core) backend with the PayPlate frontend. We do NOT add a full server project here — the code below is a snippet you can copy into your preferred ASP.NET project.

## Minimal API example (ASP.NET Core)

```csharp
// Program.cs (ASP.NET Core 6+ minimal API)
var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

app.MapGet("/api/restaurants", () => new[] {
    new { id = "greenhouse-deli", name = "Greenhouse Deli", cuisine = "Bowls · Smoothies" }
});

app.MapGet("/api/menu", () => new[] {
    new { id = "harvest-bowl", restaurantId = "greenhouse-deli", name = "Harvest Bowl", priceCents = 8600 }
});

app.Run();
```

## Calling from the frontend

Use fetch or your preferred HTTP client to call the API.

```ts
const restaurants = await fetch('/api/restaurants').then(r => r.json());
```

## Notes
- If you want a full sample server in this repository, I can add an isolated `/api` folder with an ASP.NET Core template, but that requires the .NET SDK in CI and additional maintenance.
- This snippet is intentionally minimal so you can copy it into any backend project.

/*
# PayPlate Core Schema — Phase 1

## Overview
Creates the foundational database tables for the PayPlate student food & wallet ecosystem.

## New Tables
1. **profiles** — extends auth.users with student-specific fields (full name, university, student number, verification status, reward tier)
2. **restaurants** — campus restaurants with hero images, ratings, opening hours, student discounts
3. **menu_items** — food items belonging to restaurants, with categories, prices, dietary tags
4. **orders** — student food orders with status tracking, payment method, delivery/pickup type
5. **order_items** — line items for each order (quantity, price snapshot)
6. **transactions** — wallet transactions (top-ups, payments, refunds, rewards)
7. **rewards** — redeemable rewards with tier requirements and point costs

## Security (RLS)
- **profiles**: users can read/update only their own profile
- **restaurants**: public read (all authenticated users can browse restaurants)
- **menu_items**: public read
- **orders**: users can read/insert only their own orders
- **order_items**: users can read items for their own orders (via parent order ownership)
- **transactions**: users can read/insert only their own transactions
- **rewards**: public read (all authenticated users can see available rewards)

## Important Notes
1. profiles.id references auth.users(id) with ON DELETE CASCADE — when a user is deleted, their profile is automatically removed
2. profiles.user_id defaults to auth.uid() so inserts from authenticated clients work without explicitly passing user_id
3. orders.user_id defaults to auth.uid() for the same reason
4. All amount columns use integer cents (e.g. 7200 = R72.00) to avoid floating-point issues
5. order_items.price_cents snapshots the price at order time — if menu item prices change later, historical orders remain accurate
*/

-- === 1. profiles ===
CREATE TABLE IF NOT EXISTS profiles (
  id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  full_name text NOT NULL DEFAULT '',
  avatar_url text,
  role text NOT NULL DEFAULT 'student' CHECK (role IN ('student', 'staff', 'admin')),
  verification_status text NOT NULL DEFAULT 'unverified' CHECK (verification_status IN ('unverified', 'pending', 'verified', 'rejected')),
  university text,
  student_number text,
  faculty text,
  campus text,
  reward_tier text NOT NULL DEFAULT 'bronze' CHECK (reward_tier IN ('bronze', 'silver', 'gold', 'diamond')),
  reward_points integer NOT NULL DEFAULT 0,
  wallet_balance_cents integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE profiles ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "select_own_profile" ON profiles;
CREATE POLICY "select_own_profile" ON profiles FOR SELECT
  TO authenticated USING (auth.uid() = id);

DROP POLICY IF EXISTS "update_own_profile" ON profiles;
CREATE POLICY "update_own_profile" ON profiles FOR UPDATE
  TO authenticated USING (auth.uid() = id) WITH CHECK (auth.uid() = id);

-- === 2. restaurants ===
CREATE TABLE IF NOT EXISTS restaurants (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL,
  cuisine text NOT NULL,
  hero_image text NOT NULL,
  logo_image text,
  rating numeric(2,1) NOT NULL DEFAULT 0,
  review_count integer NOT NULL DEFAULT 0,
  eta_minutes integer NOT NULL DEFAULT 15,
  distance text NOT NULL DEFAULT '',
  discount_label text NOT NULL DEFAULT '',
  student_discount_percent integer NOT NULL DEFAULT 0,
  categories text[] NOT NULL DEFAULT '{}',
  is_open boolean NOT NULL DEFAULT true,
  opening_hours jsonb NOT NULL DEFAULT '[]',
  tags text[] NOT NULL DEFAULT '{}',
  created_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE restaurants ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "read_restaurants" ON restaurants;
CREATE POLICY "read_restaurants" ON restaurants FOR SELECT
  TO authenticated USING (true);

-- === 3. menu_items ===
CREATE TABLE IF NOT EXISTS menu_items (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  restaurant_id uuid NOT NULL REFERENCES restaurants(id) ON DELETE CASCADE,
  name text NOT NULL,
  description text NOT NULL DEFAULT '',
  price_cents integer NOT NULL,
  image text NOT NULL,
  prep_time_minutes integer NOT NULL DEFAULT 10,
  calories integer,
  dietary_tags text[] NOT NULL DEFAULT '{}',
  is_popular boolean NOT NULL DEFAULT false,
  category text NOT NULL,
  rating numeric(2,1),
  popularity_count integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE menu_items ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "read_menu_items" ON menu_items;
CREATE POLICY "read_menu_items" ON menu_items FOR SELECT
  TO authenticated USING (true);

CREATE INDEX IF NOT EXISTS idx_menu_items_restaurant ON menu_items(restaurant_id);

-- === 4. orders ===
CREATE TABLE IF NOT EXISTS orders (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL DEFAULT auth.uid() REFERENCES auth.users(id) ON DELETE CASCADE,
  restaurant_id uuid REFERENCES restaurants(id),
  restaurant_name text NOT NULL,
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'preparing', 'ready', 'delivered', 'cancelled')),
  order_type text NOT NULL DEFAULT 'delivery' CHECK (order_type IN ('delivery', 'pickup')),
  payment_method text NOT NULL DEFAULT 'wallet' CHECK (payment_method IN ('wallet', 'card')),
  subtotal_cents integer NOT NULL,
  student_discount_cents integer NOT NULL DEFAULT 0,
  promo_discount_cents integer NOT NULL DEFAULT 0,
  delivery_fee_cents integer NOT NULL DEFAULT 0,
  total_cents integer NOT NULL,
  estimated_ready_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE orders ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "select_own_orders" ON orders;
CREATE POLICY "select_own_orders" ON orders FOR SELECT
  TO authenticated USING (auth.uid() = user_id);

DROP POLICY IF EXISTS "insert_own_orders" ON orders;
CREATE POLICY "insert_own_orders" ON orders FOR INSERT
  TO authenticated WITH CHECK (auth.uid() = user_id);

DROP POLICY IF EXISTS "update_own_orders" ON orders;
CREATE POLICY "update_own_orders" ON orders FOR UPDATE
  TO authenticated USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);

CREATE INDEX IF NOT EXISTS idx_orders_user ON orders(user_id);

-- === 5. order_items ===
CREATE TABLE IF NOT EXISTS order_items (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  order_id uuid NOT NULL REFERENCES orders(id) ON DELETE CASCADE,
  menu_item_id uuid REFERENCES menu_items(id),
  name text NOT NULL,
  quantity integer NOT NULL CHECK (quantity > 0),
  price_cents integer NOT NULL,
  image text
);

ALTER TABLE order_items ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "select_own_order_items" ON order_items;
CREATE POLICY "select_own_order_items" ON order_items FOR SELECT
  TO authenticated USING (
    EXISTS (SELECT 1 FROM orders WHERE orders.id = order_items.order_id AND orders.user_id = auth.uid())
  );

DROP POLICY IF EXISTS "insert_own_order_items" ON order_items;
CREATE POLICY "insert_own_order_items" ON order_items FOR INSERT
  TO authenticated WITH CHECK (
    EXISTS (SELECT 1 FROM orders WHERE orders.id = order_items.order_id AND orders.user_id = auth.uid())
  );

CREATE INDEX IF NOT EXISTS idx_order_items_order ON order_items(order_id);

-- === 6. transactions ===
CREATE TABLE IF NOT EXISTS transactions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL DEFAULT auth.uid() REFERENCES auth.users(id) ON DELETE CASCADE,
  type text NOT NULL CHECK (type IN ('topup', 'payment', 'refund', 'reward')),
  amount_cents integer NOT NULL,
  description text NOT NULL,
  merchant_name text,
  created_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE transactions ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "select_own_transactions" ON transactions;
CREATE POLICY "select_own_transactions" ON transactions FOR SELECT
  TO authenticated USING (auth.uid() = user_id);

DROP POLICY IF EXISTS "insert_own_transactions" ON transactions;
CREATE POLICY "insert_own_transactions" ON transactions FOR INSERT
  TO authenticated WITH CHECK (auth.uid() = user_id);

CREATE INDEX IF NOT EXISTS idx_transactions_user ON transactions(user_id);

-- === 7. rewards ===
CREATE TABLE IF NOT EXISTS rewards (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  title text NOT NULL,
  description text NOT NULL,
  tier text NOT NULL CHECK (tier IN ('bronze', 'silver', 'gold', 'diamond')),
  points_cost integer NOT NULL,
  icon text NOT NULL DEFAULT 'gift',
  is_earned boolean NOT NULL DEFAULT false,
  progress_percent integer NOT NULL DEFAULT 0
);

ALTER TABLE rewards ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "read_rewards" ON rewards;
CREATE POLICY "read_rewards" ON rewards FOR SELECT
  TO authenticated USING (true);

-- === Updated_at trigger ===
CREATE OR REPLACE FUNCTION update_updated_at()
RETURNS trigger AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS profiles_updated_at ON profiles;
CREATE TRIGGER profiles_updated_at BEFORE UPDATE ON profiles
  FOR EACH ROW EXECUTE FUNCTION update_updated_at();

DROP TRIGGER IF EXISTS orders_updated_at ON orders;
CREATE TRIGGER orders_updated_at BEFORE UPDATE ON orders
  FOR EACH ROW EXECUTE FUNCTION update_updated_at();
